$chatJobs->saveExecutionPlan($job['id'],1,['title'=>'Safe checkpoint workflow','goal'=>'Validate a resumable agent plan'],[['key'=>'inspect','title'=>'Inspect inputs','depends_on'=>[],'idempotency_key'=>'inspect-v1'],['key'=>'apply','title'=>'Apply reviewed change','depends_on'=>['inspect'],'idempotency_key'=>'apply-v1']]);$dependencyBlocked=false;try{$chatJobs->setExecutionStepStatus($job['id'],'apply','running');}catch(RuntimeException $e){$dependencyBlocked=str_contains($e->getMessage(),'dependency');}ok($dependencyBlocked,'Execution plan prevents a dependent step from running before its prerequisite is confirmed');$chatJobs->setExecutionStepStatus($job['id'],'inspect','running');$chatJobs->setExecutionStepStatus($job['id'],'inspect','completed');$toolRef=$chatJobs->recordToolResultReference($job['id'],'inspect','filesystem.read','toolres_inspect_001',hash('sha256','mock tool result'));$approval=$chatJobs->requestExecutionApproval($job['id'],'apply','production-write','Production write requires explicit user approval');ok(($toolRef['result_ref']??'')==='toolres_inspect_001'&&($approval['status']??'')==='pending','Execution plan stores opaque tool-result references and a pending approval without executing anything');$checkpoint=$chatJobs->requestCheckpoint($job['id']);ok(($checkpoint['status']??'')==='checkpoint_requested'&&($checkpoint['interrupt_requested']??false),'Chat checkpoint request records intent without cancelling the in-flight provider call');
