eckpoint snapshot contains the completed conversation and its SHA-256 context hash verifies');
$approvalState=$db->prepare('SELECT status FROM chat_job_approvals WHERE job_id=? AND approval_key=?');$approvalState->execute([$job['id'],'production-write']);ok($approvalState->fetchColumn()==='pending','Pending approval remains pending until an explicit human decision is submitted');$chatJobs->decideExecutionApproval($job['id'],'production-write','rejected','Test gate remains closed');$approvalState->execute([$job['id'],'production-write']);ok($approvalState->fetchColumn()==='rejected','Explicit approval decisions are persisted and do not trigger execution');$cycleRejected=false;try{$chatJobs->saveExecutionPlan($job['id'],2,['title'=>'Invalid cycle'],[['key'=>'a','title'=>'A','depends_on'=>['b']],['key'=>'b','title'=>'B','depends_on'=>['a']]]);}catch(InvalidArgumentException $e){$cycleRejected=str_contains($e->getMessage(),'cycle');}ok($cycleRejected,'Execution plan rejects dependency cycles before persistence');$versionRejected=false;try{$chatJobs->saveExecutionPlan($job['id'],1,['title'=>'Old plan'],[['key'=>'old','title'=>'Old','depends_on'=>[]]]);}catch(RuntimeException $e){$versionRejected=true;}ok($versionRejected,'Execution plan versions cannot move backwards or be silently overwritten');
$inboxSent=$db->prepare('SELECT status FROM task_inbox WHERE id=?');$inboxSent->execute([$inboxItem['id']]);ok($inboxSent->fetchColumn()==='sent','Task Inbox item is marked sent only after its background chat job completes');
$assistantMessage=$db->prepare("SELECT content FROM chat_messages WHERE session_id=? AND role='assistant' ORDER BY id DESC LIMIT 1");$assistantMessage->execute([$chatSession]);ok($assistantMessage->fetchColumn()==='Mock assistant reply','Chat worker stores the assistant response in the conversation history');
$queuedPause=$chatJobs->enqueue($chatSession,$p['id'],'mock-model','Pause before execution',[]);$paused=$chatJobs->requestCheckpoint($queuedPause['id']);ok(($paused['status']??'')==='checkpoint_ready'&&$chatJobs->claim($queuedPause['id'])===null,'Checkpoint requested before worker claim prevents provider execution');$pausedCheckpoint=$chatJobs->getCheckpoint($queuedPause['id']);ok(($pausedCheckpoint['snapshot']['execution_context']['step_graph_available']??true)===false&&($pausedCheckpoint['snapshot']['execution_context']['resumable']??true)===false,'Checkpoint without a recorded agent plan is explicitly non-resumable rather than inventing execution state');ok($pausedCheckpoint['checkpoint_kind']==='paused_before_provider'&&$pausedCheckpoint['snapshot']['last_provider_call']['assistant_reply']===null,'Queued-before-claim pause also creates a durable checkpoint without inventing a provider response');
$failed=$chatJobs->enqueue($chatSession,$p['id'],'mock-model','This will fail',[]);$chatJobs->claim($failed['id']);$chatJobs->fail($failed['id'],'Mock worker failure');ok(($chatJobs->get($failed['id'])['status']??'')==='failed','Chat worker failure is persisted for the UI to recover');
$expired=$chatJobs->enqueue($chatSession,$p['id'],'mock-model','Stale worker',[]);$chatJobs->claim($expired['id']);$db->prepare('UPDATE chat_jobs SET lease_until=? WHERE id=?')->execute(['2000-01-01T00:00:00+00:00',$expired['id']]);$expiredState=$chatJobs->get($expired['id']);ok(($expiredState['status']??'')==='failed'&&str_contains((string)$expiredState['error'],'lease expired'),'Chat job with an expired worker lease fails closed instead of remaining busy forever');
$badInboxRejected=false;try{$chatJobs->enqueue($chatSession,$p['id'],'mock-model','Wrong queue link',[],'missing-inbox-item');}catch(InvalidArgumentException $e){$badInboxRejected=true;}ok($badInboxRejected,'Chat job cannot consume an unknown or unrelated Task Inbox item');
